)

# 4. Helper functions

parse_logical_strict <- function(x, variable_name) {

  y <- str_to_lower(
    str_trim(
      as.character(x)
    )
  )

  result <- rep(
    NA,
    length(y)
  )

  result[
    y %in% c(
      "true",
      "t",
      "1",
      "yes",
      "y"
    )
  ] <- TRUE

  result[
    y %in% c(
      "false",
      "f",
      "0",
      "no",
      "n"
    )
  ] <- FALSE

  invalid <- is.na(result) &
    !is.na(y) &
    y != ""

  if (any(invalid)) {

    stop(
      "Unexpected value(s) in ",
      variable_name,
      ": ",
      paste(
        unique(y[invalid]),
        collapse = ", "
      ),
      call. = FALSE
    )
  }

  result
}

safe_cosine_similarity <- function(x, y) {

  if (
    anyNA(x) ||
    anyNA(y) ||
    sum(x) == 0 ||
    sum(y) == 0
  ) {

    return(
      NA_real_
    )
  }

  sum(x * y) /
    (
      sqrt(sum(x^2)) *
        sqrt(sum(y^2))
    )
}


write_matrix_tsv <- function(
    x,
    row_name,
    path
) {

  out <- as.data.frame(
    x,
    check.names = FALSE
  ) %>%
    rownames_to_column(
      row_name
    )

  write_tsv(
    out,
    path
  )
}

make_granges <- function(df) {

  gr <- GRanges(
    seqnames = df$chr,

    ranges = IRanges(
      start = df$pos,
      width = 1
    ),

    REF = df$ref,
    ALT = df$alt
  )

  GenomeInfoDb::genome(gr) <- "hg38"

  gr
}

# 5. Validate input paths

if (!dir.exists(STEP2_DIR)) {

  stop(
