    call. = FALSE
  )
}


meta_all <- meta_all %>%
  mutate(

    patient =
      str_trim(patient),

    vcf_sample_id =
      str_trim(vcf_sample_id),

    sample_id =
      str_trim(sample_id),

    role =
      str_to_lower(
        str_trim(role)
      ),

    signature_pair_selected =
      parse_logical_strict(
        signature_pair_selected,
        "signature_pair_selected"
      )
  )


allowed_roles <- c(
  "blood",
  "tumor",
  "adjacent"
)

bad_roles <- setdiff(
  unique(meta_all$role),
  allowed_roles
)

if (length(bad_roles) > 0) {

  stop(
    "Unexpected metadata role(s): ",
    paste(
      bad_roles,
      collapse = ", "
    ),
    call. = FALSE
  )
}

if (anyDuplicated(meta_all$sample_id)) {

  stop(
    "Duplicated sample_id values detected in metadata.",
    call. = FALSE
  )
}

# 7. Find Step 2 candidate-somatic files

step2_files <- list.files(
  STEP2_DIR,
  pattern = "_candidate_somatic_long\\.tsv$",
  full.names = TRUE,
  recursive = TRUE
)

step2_files <- sort(
  step2_files
)

if (length(step2_files) == 0) {

  stop(
    "No *_candidate_somatic_long.tsv files found under:\n",
    STEP2_DIR,
    call. = FALSE
  )
}

processed_patients <- basename(
  step2_files
) %>%
  str_remove(
    "_candidate_somatic_long\\.tsv$"
  )

if (anyDuplicated(processed_patients)) {

  stop(
    "More than one candidate-somatic file was found ",
    "for at least one patient.",
    call. = FALSE
  )
}

missing_patients <- setdiff(
  processed_patients,
  meta_all$patient
)

if (length(missing_patients) > 0) {

  stop(
    "Step 2 patient(s) missing from metadata: ",
    paste(
      missing_patients,
      collapse = ", "
    ),
    call. = FALSE
  )
}


cat(
  "Step 2 patient files found:",
  length(step2_files),
  "\n"
)

# 8. Load Step 2 candidate-somatic data

read_step2_file <- function(path) {

  expected_patient <- basename(path) %>%
    str_remove(
      "_candidate_somatic_long\\.tsv$"
    )

  dat <- read_tsv(
    path,
    col_types = cols(.default = "c"),
    show_col_types = FALSE,
    progress = FALSE
  )

  if (
    nrow(dat) > 0 &&
    "patient" %in% names(dat)
  ) {

    patient_values <- unique(
      str_trim(
        dat$patient
      )
    )

    patient_values <- patient_values[
      !is.na(patient_values) &
        patient_values != ""
    ]

    if (
      length(patient_values) != 1L ||
      patient_values != expected_patient
    ) {

      stop(
        "Patient identifier in file does not match filename:\n",
        path,
        call. = FALSE
      )
    }
  }

  dat
}

candidate_long <- map_dfr(
  step2_files,
  read_step2_file
)

required_step2_columns <- c(
  "patient",
  "sample_id",
  "role",
  "chr",
  "pos",
  "ref",
  "alt",
  "present",
  "is_candidate_somatic"
)

missing_step2_columns <- setdiff(
  required_step2_columns,
  names(candidate_long)
)

if (length(missing_step2_columns) > 0) {

  stop(
    "Step 2 output is missing required column(s): ",
    paste(
      missing_step2_columns,
      collapse = ", "
    ),
    call. = FALSE
  )
}

candidate_long <- candidate_long %>%
  mutate(

    patient =
      str_trim(patient),

    sample_id =
      str_trim(sample_id),

    role =
      str_to_lower(
        str_trim(role)
      ),

    chr =
      str_trim(chr),

    pos =
      suppressWarnings(
        as.integer(pos)
      ),

    ref =
      str_to_upper(
        str_trim(ref)
      ),

    alt =
      str_to_upper(
        str_trim(alt)
      ),

    present =
      parse_logical_strict(
        present,
        "present"
      ),

    is_candidate_somatic =
      parse_logical_strict(
        is_candidate_somatic,
        "is_candidate_somatic"
      )
  )


# 9. Validate sample identity and roles

step2_roles <- candidate_long %>%
  dplyr::distinct(
    patient,
    sample_id,
    role
  ) %>%
  dplyr::rename(
    step2_role = role
  )

metadata_roles <- meta_all %>%
  dplyr::select(
    patient,
    sample_id,
    metadata_role = role
  )

role_check <- step2_roles %>%
  left_join(
    metadata_roles,
    by = c(
      "patient",
      "sample_id"
    )
  )

missing_sample_metadata <- role_check %>%
  filter(
    is.na(metadata_role)
  )


if (nrow(missing_sample_metadata) > 0) {

  print(
    missing_sample_metadata
  )

  stop(
    "At least one Step 2 sample is absent from sample metadata.",
    call. = FALSE
  )
}

role_mismatches <- role_check %>%
  filter(
    step2_role != metadata_role
  )


if (nrow(role_mismatches) > 0) {

  print(
    role_mismatches
  )

  stop(
    "Sample-role mismatch between Step 2 and metadata.",
    call. = FALSE
  )
}

# 10. Retain somatic SNVs present in each tissue

present_tissue_variants <- candidate_long %>%
  filter(
    is_candidate_somatic,
    present,
    role %in% c(
      "tumor",
      "adjacent"
    )
  )

bad_snvs <- present_tissue_variants %>%
  filter(
    is.na(chr) |
      is.na(pos) |
      pos < 1 |
      is.na(ref) |
      is.na(alt) |
      nchar(ref) != 1 |
      nchar(alt) != 1 |
      !ref %in% c(
        "A",
        "C",
        "G",
        "T"
      ) |
      !alt %in% c(
        "A",
        "C",
        "G",
        "T"
      ) |
      ref == alt
  )


if (nrow(bad_snvs) > 0) {

  print(
    head(
      bad_snvs,
      20
    )
  )

  stop(
    "Unexpected non-SNV or malformed records detected ",
    "in the Step 2 candidate-somatic dataset.",
    call. = FALSE
  )
}

snvs <- present_tissue_variants %>%
  distinct(
    patient,
    sample_id,
    role,
    chr,
    pos,
    ref,
    alt
  )


if (nrow(snvs) == 0) {

  stop(
    "No candidate somatic SNVs are present in tumor/adjacent samples.",
    call. = FALSE
  )
}


cat(
  "Sample-level somatic SNV observations:",
  nrow(snvs),
  "\n"
)

# 11. Validate chromosomes against the reference genome

ref_genome <-
  BSgenome.Hsapiens.UCSC.hg38


reference_seqnames <-
  seqnames(
    ref_genome
  )


unsupported_chromosomes <- setdiff(
  unique(snvs$chr),
  reference_seqnames
)


if (length(unsupported_chromosomes) > 0) {

  stop(
    "Chromosome(s) absent from BSgenome.Hsapiens.UCSC.hg38: ",
    paste(
      unsupported_chromosomes,
      collapse = ", "
    ),
    call. = FALSE
  )
}

# 12. Define tissue samples included in the analysis

analysis_meta <- meta_all %>%
  filter(
    patient %in% processed_patients,
    role %in% c(
      "tumor",
      "adjacent"
    )
  ) %>%
  arrange(
    patient,
    role,
    sample_id
  )


if (nrow(analysis_meta) == 0) {

  stop(
    "No tumor or adjacent samples were found for processed patients.",
    call. = FALSE
  )
}

# 13. Validate predefined tumor-NAT pairs

patient_tissue_status <- analysis_meta %>%
  group_by(
    patient
  ) %>%
  summarise(

    has_tumor =
      any(
        role == "tumor"
      ),

    has_adjacent =
      any(
        role == "adjacent"
      ),

    .groups = "drop"
  )


eligible_pair_patients <- patient_tissue_status %>%
  filter(
    has_tumor,
    has_adjacent
  ) %>%
  pull(
    patient
  )

selected_pair_samples <- analysis_meta %>%
  filter(
    signature_pair_selected
  )

selected_ineligible <- selected_pair_samples %>%
  filter(
    !patient %in% eligible_pair_patients
  )

if (nrow(selected_ineligible) > 0) {

  print(
    selected_ineligible
  )

  stop(
    "signature_pair_selected = TRUE was assigned to a patient ",
    "without both tumor and adjacent tissue.",
    call. = FALSE
  )
}

pair_selection_check <- selected_pair_samples %>%
  filter(
    patient %in% eligible_pair_patients
  ) %>%
  count(
    patient,
    role
  ) %>%
  complete(
    patient = eligible_pair_patients,
    role = c(
      "tumor",
      "adjacent"
    ),
    fill = list(
      n = 0L
    )
  ) %>%
  pivot_wider(
    names_from = role,
    values_from = n,
    values_fill = 0L
  )

bad_pair_selection <- pair_selection_check %>%
  filter(
    tumor != 1L |
      adjacent != 1L
  )


if (nrow(bad_pair_selection) > 0) {

  print(
    bad_pair_selection
  )

  stop(
    "Each patient with both tumor and adjacent tissue must have ",
    "exactly one tumor and one adjacent sample marked ",
    "signature_pair_selected = TRUE.",
    call. = FALSE
  )
}

# 14. Construct per-sample GRanges objects

per_sample <- split(snvs, snvs$sample_id)

grl <- GRangesList(lapply(per_sample, make_granges))

names(grl) <- names(per_sample)

# 15. Construct SBS96 mutation matrix

mut_mat <- mut_matrix(
  vcf_list = grl,
  ref_genome = ref_genome
)

if (nrow(mut_mat) != 96L) {

  stop(
    "Expected a 96-context SBS mutation matrix; obtained ",
    nrow(mut_mat),
    " rows.",
    call. = FALSE
  )
}

write_matrix_tsv(mut_mat, "context", file.path(OUT_DIR, "cohort_SBS96_matrix.tsv"))

saveRDS(mut_mat, file.path(OUT_DIR, "cohort_SBS96_matrix.rds"))

# 16. Sample-level mutation-count QC

snv_counts <- tibble(

  sample_id =
    colnames(mut_mat),

  n_snv =
    as.integer(
      colSums(mut_mat)
    )
)

sample_qc <- analysis_meta %>%
  select(
    patient,
    sample_id,
    role,
    signature_pair_selected
  ) %>%
  left_join(
    snv_counts,
    by = "sample_id"
  ) %>%
  mutate(

    n_snv =
      replace_na(
        n_snv,
        0L
      ),

    fit_included =
      n_snv > 0L,

    confidence = case_when(

      n_snv == 0L ~
        NA_character_,

      n_snv > HIGH_CONFIDENCE_THRESHOLD ~
        "high",

      n_snv >= MEDIUM_CONFIDENCE_THRESHOLD ~
        "medium",

      TRUE ~
        "low"
    )
  )

cat("\nMutation-count confidence categories:\n")

print(table(sample_qc$role, sample_qc$confidence, useNA = "ifany"))

# 17. Retrieve COSMIC v3.2 GRCh38 signatures

all_signatures <- get_known_signatures(
  muttype = "snv",
  source = COSMIC_VERSION,
  genome = REFERENCE_GENOME
)

missing_signatures <- setdiff(
  SIGNATURE_PANEL,
  colnames(all_signatures)
)

if (length(missing_signatures) > 0) {
  
  stop(
    "COSMIC v3.2 reference is missing requested signature(s): ",
    paste(
      missing_signatures,
      collapse = ", "
    ),
    call. = FALSE
  )
}

if (nrow(all_signatures) != nrow(mut_mat)) {
  
  stop(
    "Mutation matrix and COSMIC signature matrix have different ",
    "numbers of SBS contexts: ",
    nrow(mut_mat),
    " vs ",
    nrow(all_signatures),
    ".",
    call. = FALSE
  )
}

signatures <- all_signatures[
  ,
  SIGNATURE_PANEL,
  drop = FALSE
]

# Add the descriptive SBS96 context names from the mutation matrix.
# The MutationalPatterns matrices already use the same canonical 96-context ordering.

rownames(signatures) <- rownames(mut_mat)

saveRDS(
  signatures,
  file.path(
    OUT_DIR,
    "COSMIC_v3.2_selected_signatures.rds"
  )
)

signature_panel_table <- tibble(
  signature = SIGNATURE_PANEL,
  cosmic_version = COSMIC_VERSION,
  genome = REFERENCE_GENOME
)

write_tsv(signature_panel_table, file.path(OUT_DIR, "signature_panel_used.tsv"))

# 18. Fit signatures

fit_samples <- sample_qc %>%
  filter(
    fit_included
  ) %>%
  pull(
    sample_id
  )

fit_samples <- intersect(
  fit_samples,
  colnames(mut_mat)
)

if (length(fit_samples) == 0) {

  stop(
    "No samples contain SNVs available for signature fitting.",
    call. = FALSE
  )
}

mut_mat_fit <- mut_mat[
  ,
  fit_samples,
  drop = FALSE
]

fit_strict <- fit_to_signatures_strict(
  mut_mat = mut_mat_fit,
  signatures = signatures,
  max_delta = MAX_DELTA
)

saveRDS(
  fit_strict,
  file.path(
    OUT_DIR,
    "signature_strict_fit.rds"
  )
)

fit_contribution <- fit_strict$fit_res$contribution

contrib_abs <- matrix(
  0,
  nrow = length(SIGNATURE_PANEL),
  ncol = length(fit_samples),
  dimnames = list(
    SIGNATURE_PANEL,
    fit_samples
  )
)

common_signatures <- intersect(
  rownames(fit_contribution),
  SIGNATURE_PANEL
)

common_samples <- intersect(
  colnames(fit_contribution),
  fit_samples
)

contrib_abs[
  common_signatures,
  common_samples
] <- fit_contribution[
  common_signatures,
  common_samples,
  drop = FALSE
]

# 19. Calculate relative signature contributions

contribution_totals <- colSums(contrib_abs)

if (any(contribution_totals <= 0)) {

  stop(
    "At least one fitted sample has zero total signature contribution.",
    call. = FALSE
  )
}

contrib_rel <- sweep(
  contrib_abs,
  2,
  contribution_totals,
  "/"
)

write_matrix_tsv(
  contrib_abs,
  "signature",
  file.path(
    OUT_DIR,
    "signature_contributions_absolute.tsv"
  )
)

write_matrix_tsv(
  contrib_rel,
  "signature",
  file.path(
    OUT_DIR,
    "signature_contributions_relative.tsv"
  )
)

# 20. Calculate reconstruction accuracy

reconstructed <- signatures %*%
  contrib_abs

cosine_similarity <- map_dbl(
  fit_samples,

  function(sample_id) {

    safe_cosine_similarity(

      mut_mat_fit[
        ,
        sample_id
      ],

      reconstructed[
        ,
        sample_id
      ]
    )
  }
)

reconstruction_qc <- tibble(

  sample_id =
    fit_samples,

  cosine_similarity =
    cosine_similarity
)


sample_qc <- sample_qc %>%
  left_join(
    reconstruction_qc,
    by = "sample_id"
  )


write_tsv(
  sample_qc,
  file.path(
    OUT_DIR,
    "signature_sample_qc.tsv"
  )
)

write_matrix_tsv(
  reconstructed,
  "context",
  file.path(
    OUT_DIR,
    "cohort_SBS96_reconstructed.tsv"
  )
)

# 21. Create long-format signature contribution table

absolute_long <- as.data.frame(
  t(contrib_abs),
  check.names = FALSE
) %>%
  rownames_to_column(
    "sample_id"
  ) %>%
  pivot_longer(
    -sample_id,
    names_to = "signature",
    values_to = "absolute_contribution"
  )

relative_long <- as.data.frame(
  t(contrib_rel),
  check.names = FALSE
) %>%
  rownames_to_column(
    "sample_id"
  ) %>%
  pivot_longer(
    -sample_id,
    names_to = "signature",
    values_to = "relative_contribution"
  )

contrib_long <- absolute_long %>%
  left_join(
    relative_long,
    by = c(
      "sample_id",
      "signature"
    )
  ) %>%
  left_join(
    sample_qc,
    by = "sample_id"
  ) %>%
  select(
    patient,
    sample_id,
    role,
    signature_pair_selected,
    n_snv,
    confidence,
    cosine_similarity,
    signature,
    absolute_contribution,
    relative_contribution
  ) %>%
  arrange(
    patient,
    sample_id,
    signature
  )

write_tsv(
  contrib_long,
  file.path(
    OUT_DIR,
    "signature_contributions_long.tsv"
  )
)

# 22. Contribution heatmap and sample-level plots

active_signatures <- rownames(
  contrib_abs
)[
  rowSums(
    contrib_abs
  ) > 0
]

if (length(active_signatures) > 0) {

  pdf(
    file.path(
      OUT_DIR,
      "signature_contribution_heatmap.pdf"
    ),
    width = 11,
    height = max(
      6,
      0.20 * length(fit_samples)
    )
  )

  print(
    plot_contribution_heatmap(
      contrib_rel[
        active_signatures,
        fit_samples,
        drop = FALSE
      ],
      cluster_samples = TRUE
    )
  )

  dev.off()

  plot_groups <- list(

    all =
      fit_samples,

    tumor =
      intersect(
        fit_samples,
        sample_qc$sample_id[
          sample_qc$role == "tumor"
        ]
      ),

    adjacent =
      intersect(
        fit_samples,
        sample_qc$sample_id[
          sample_qc$role == "adjacent"
        ]
      )
  )


  for (group_name in names(plot_groups)) {

    sample_ids <-
      plot_groups[[group_name]]

    if (length(sample_ids) == 0) {
      next
    }


    pdf(
      file.path(
        OUT_DIR,
        paste0(
          "signature_contributions_",
          group_name,
          ".pdf"
        )
      ),

      width = max(
        10,
        0.24 * length(sample_ids)
      ),

      height = 7
    )


    print(
      plot_contribution(

        contrib_abs[
          active_signatures,
          sample_ids,
          drop = FALSE
        ],

        mode = "relative",

        coord_flip = TRUE
      )
    )


    dev.off()
  }
}

