# 25. Paired Wilcoxon signed-rank tests

run_paired_wilcoxon <- function(signature_name) {

  dat <- paired_contributions %>%
    filter(
      signature == signature_name,
      is.finite(tumor),
      is.finite(nat)
    )

  n_pairs <- nrow(dat)


  differences <- dat$tumor - dat$nat

  V_statistic <- NA_real_
  p_value <- NA_real_

  if (n_pairs >= MIN_PAIRS_FOR_TEST) {

    if (all(differences == 0)) {

      V_statistic <- 0
      p_value <- 1

    } else {

      test <- suppressWarnings(
        wilcox.test(
          dat$tumor,
          dat$nat,
          paired = TRUE,
          alternative = "two.sided",
          exact = FALSE,
          correct = TRUE
        )
      )


      V_statistic <-
        unname(
          test$statistic
        )


      p_value <-
        test$p.value
    }
  }

  tibble(

    signature = signature_name,
    n_pairs = n_pairs,
    n_nonzero_pairs = sum(differences != 0),
    n_tumor_higher = sum(differences > 0),
    n_nat_higher = sum(differences < 0),
    n_equal = sum(differences == 0),
    median_tumor =
      if (n_pairs > 0) {
        median(dat$tumor)
      } else {
        NA_real_
      },
    median_nat =
      if (n_pairs > 0) {
        median(dat$nat)
      } else {
        NA_real_
      },
    median_paired_difference =
      if (n_pairs > 0) {
        median(differences)
      } else {
        NA_real_
      },
    V_statistic =
      V_statistic,
    p_value =
      p_value,
    test_ran =
      n_pairs >= MIN_PAIRS_FOR_TEST
  )
}


wilcox_results <- map_dfr(
  SIGNATURE_PANEL,
  run_paired_wilcoxon
) %>%
  mutate(
    p_adjusted_BH =
      p.adjust(
        p_value,
        method = "BH"
      ),
    significant = case_when(
      is.na(p_adjusted_BH) ~
        NA_character_,

      p_adjusted_BH < 0.001 ~
        "***",

      p_adjusted_BH < 0.01 ~
        "**",

      p_adjusted_BH < 0.05 ~
        "*",

      TRUE ~
        "ns"
    ),

    direction = case_when(
      n_tumor_higher > n_nat_higher ~
        "tumor_higher",
      n_nat_higher > n_tumor_higher ~
        "nat_higher",
      n_tumor_higher == n_nat_higher &
        n_nonzero_pairs > 0 ~
        "balanced",
      TRUE ~
        "no_nonzero_differences"
    )
  ) %>%
  arrange(p_value)

write_tsv(wilcox_results, file.path(OUT_DIR, "signature_wilcoxon_tumor_vs_nat.tsv"))

